package cli

import (
	"archive/tar"
	"archive/zip"
	"compress/gzip"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"time"
)

// Release-asset download. The one irreducibly forge-specific piece of the
// plugin system is where release binaries live; it's contained here as a
// small per-host URL convention table with a declarative escape hatch
// (download_url in entire-plugin.yml). Everything else — version listing,
// metadata, the index — runs on the git protocol.

// errAssetNotFound distinguishes "this tag has no matching asset" (worth
// trying the next-highest tag — a pushed tag whose release isn't published
// yet) from transport errors (not worth retrying on another tag).
var errAssetNotFound = errors.New("no matching release asset")

// errUnverifiedAsset means an asset was reachable but nothing authenticated
// it — no checksums.txt covering this platform. Distinct from
// errAssetNotFound so it never triggers the next-highest-tag walk: falling
// back to an older tag wouldn't make the download any more trustworthy.
var errUnverifiedAsset = errors.New("release asset cannot be verified")

// requireSecureAssetURL gates every plugin HTTP fetch on a transport that a
// network attacker can't rewrite.
//
// Plaintext HTTP is not merely "less good" here: the asset and the
// checksums.txt that authenticates it come from the same origin, so an
// attacker who can rewrite one can rewrite both, and checksum verification
// becomes theatre. HTTPS is therefore required for anything off-machine.
//
// Loopback is exempt so httptest-backed tests and local forge experiments
// keep working — traffic that never leaves the machine has no network
// attacker to defend against.
func requireSecureAssetURL(rawURL string) error {
	u, err := url.Parse(rawURL)
	if err != nil {
		return fmt.Errorf("parse download URL %q: %w", redactURL(rawURL), err)
	}
	switch strings.ToLower(u.Scheme) {
	case "https":
		return nil
	case "http":
		if isLoopbackHost(u.Hostname()) {
			return nil
		}
		return fmt.Errorf("refusing to download %s over plaintext HTTP: the asset and its %s would share an origin, so a network attacker could replace both and checksum verification would prove nothing; serve the release over HTTPS or declare an https download_url in %s",
			redactURL(rawURL), checksumsFileName, pluginMetadataFileName)
	default:
		return fmt.Errorf("plugin downloads must use https; %q has scheme %q", redactURL(rawURL), u.Scheme)
	}
}

// isLoopbackHost reports whether host addresses this machine.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	if ip := net.ParseIP(host); ip != nil {
		return ip.IsLoopback()
	}
	return false
}

// maxAssetRedirects bounds the redirect chain for an asset fetch. Release
// hosts routinely redirect to a CDN, so some hops are expected.
const maxAssetRedirects = 10

// pluginHTTPClient bounds the total time for a single asset download.
// Plugins can be tens of MB; 5 minutes is generous even on slow links.
//
// CheckRedirect re-runs the transport check on every hop. Without it the
// https-only rule is trivially bypassed: Go's default policy follows up to 10
// redirects *across schemes* and only the initial URL was ever validated, so an
// https:// entry point could deliver both the asset and its checksums.txt over
// plaintext — exactly the outcome requireSecureAssetURL exists to prevent.
var pluginHTTPClient = &http.Client{
	Timeout: 5 * time.Minute,
	CheckRedirect: func(req *http.Request, via []*http.Request) error {
		if len(via) >= maxAssetRedirects {
			return fmt.Errorf("stopped after %d redirects", maxAssetRedirects)
		}
		return requireSecureAssetURL(req.URL.String())
	},
}

// maxPluginAssetSize caps a downloaded asset. Real plugin binaries are tens
// of MB; the cap exists so a misconfigured URL serving an endless stream
// can't fill the disk.
const maxPluginAssetSize = 512 << 20 // 512 MiB

// maxChecksumsSize caps a checksums.txt fetch. One line per released artifact,
// so 1 MiB covers thousands.
const maxChecksumsSize = 1 << 20

// releaseAssetBaseURL returns the URL prefix release assets live under for
// the repo's host. GitHub and the Gitea family share a convention; GitLab
// has its own. Unknown hosts default to the GitHub-style convention (most
// self-hosted forges mirror it) — authors on hosts that don't can declare
// download_url in entire-plugin.yml.
func releaseAssetBaseURL(repoURL, tag string) (string, error) {
	u, err := url.Parse(strings.TrimSuffix(repoURL, ".git"))
	if err != nil {
		return "", fmt.Errorf("parse repo URL: %w", err)
	}
	if u.Scheme != "https" && u.Scheme != "http" {
		return "", fmt.Errorf("release downloads need an http(s) repo URL, got %q (declare download_url in %s for non-HTTP remotes)", redactURL(repoURL), pluginMetadataFileName)
	}
	base := strings.TrimSuffix(u.String(), "/")
	host := strings.ToLower(u.Hostname())
	if host == "gitlab.com" || strings.HasPrefix(host, "gitlab.") {
		return base + "/-/releases/" + url.PathEscape(tag) + "/downloads/", nil
	}
	return base + "/releases/download/" + url.PathEscape(tag) + "/", nil
}

// expandDownloadTemplate expands the author-declared download_url template.
// Placeholders: {name} {tag} {version} {os} {arch} {asset}.
func expandDownloadTemplate(tmpl, name, tag, asset string) string {
	r := strings.NewReplacer(
		"{name}", name,
		"{tag}", tag,
		"{version}", strings.TrimPrefix(tag, "v"),
		"{os}", runtime.GOOS,
		"{arch}", runtime.GOARCH,
		"{asset}", asset,
	)
	return r.Replace(tmpl)
}

// archAliases maps a GOARCH to the spellings seen in release asset names.
func archAliases(goarch string) []string {
	switch goarch {
	case "amd64":
		return []string{"amd64", "x86_64"}
	case "arm64":
		return []string{"arm64", "aarch64"}
	default:
		return []string{goarch}
	}
}

// osAliases maps a GOOS to asset-name spellings, most specific first.
func osAliases(goos string) []string {
	if goos == darwinGOOS {
		return []string{"darwin", "macos"}
	}
	return []string{goos}
}

// platformArchAliases returns the arch spellings to try for goos. On darwin it
// appends "all", which is where goreleaser puts the universal-binary marker:
// the name is entire-<x>_<ver>_darwin_all, so "all" belongs in the arch slot.
// It used to sit in the OS slot, generating _all_arm64 — a spelling no forge
// produces — so the darwin_all fallback the docs promise never actually
// matched and universal-only releases could not be installed at all.
func platformArchAliases(goos, goarch string) []string {
	aliases := archAliases(goarch)
	if goos == darwinGOOS {
		aliases = append(aliases, "all")
	}
	return aliases
}

// assetCandidates returns release asset filenames to try for this platform,
// in preference order: archives before raw binaries, version-in-name
// (goreleaser's default template) before version-less.
func assetCandidates(name, tag string) []string {
	binName := pluginBinaryPrefix + name
	version := strings.TrimPrefix(tag, "v")
	stems := make([]string, 0, 16)
	for _, osName := range osAliases(runtime.GOOS) {
		for _, arch := range platformArchAliases(runtime.GOOS, runtime.GOARCH) {
			stems = append(stems,
				fmt.Sprintf("%s_%s_%s_%s", binName, version, osName, arch),
				fmt.Sprintf("%s_%s_%s", binName, osName, arch),
			)
		}
	}
	exts := []string{".tar.gz", ".zip", ""}
	if runtime.GOOS == windowsGOOS {
		exts = []string{".zip", ".tar.gz", windowsExeExt}
	}
	var out []string
	for _, ext := range exts {
		for _, stem := range stems {
			out = append(out, stem+ext)
		}
	}
	return out
}

// checksumsFileName is the conventional name of a release's checksum
// manifest (goreleaser's default).
const checksumsFileName = "checksums.txt"

// checksumCandidates returns filenames the checksum manifest may go by.
func checksumCandidates(name, tag string) []string {
	binName := pluginBinaryPrefix + name
	version := strings.TrimPrefix(tag, "v")
	return []string{
		checksumsFileName,
		fmt.Sprintf("%s_%s_checksums.txt", binName, version),
		binName + "_checksums.txt",
	}
}

// parseChecksums parses "hex  filename" lines (sha256sum format) into a
// filename → digest map.
func parseChecksums(data []byte) map[string]string {
	out := make(map[string]string)
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 2 {
			continue
		}
		// sha256sum marks binary-mode files with a leading *.
		out[strings.TrimPrefix(fields[1], "*")] = strings.ToLower(fields[0])
	}
	return out
}

// selectAssetFromChecksums picks the preferred candidate present in the
// checksum manifest. The manifest lists what was actually published, so
// this avoids probing candidate URLs one by one.
func selectAssetFromChecksums(sums map[string]string, name, tag string) (asset, digest string, ok bool) {
	for _, c := range assetCandidates(name, tag) {
		if d, present := sums[c]; present {
			return c, d, true
		}
	}
	return "", "", false
}

// fetchedAsset is the result of downloadPluginAsset: a verified asset on
// disk in a caller-owned staging dir.
type fetchedAsset struct {
	// Path is the downloaded asset file inside the staging dir.
	Path string
	// Asset is the asset filename that matched.
	Asset string
	// SHA256 is the hex digest of the downloaded bytes.
	SHA256 string
	// Verified is true when SHA256 was checked against a digest published in
	// the release's checksum manifest, rather than merely computed from
	// whatever arrived. Recorded in the install manifest so `plugin doctor`
	// can surface unverified installs.
	Verified bool
}

// downloadPluginAsset locates and downloads the release asset for name@tag
// into stagingDir, verifying against the release's checksum manifest when
// one is published. Returns errAssetNotFound (possibly wrapped) when the
// tag has no asset for this platform.
func downloadPluginAsset(ctx context.Context, meta *PluginMetadata, repoURL, name, tag, stagingDir string, allowUnverified bool) (*fetchedAsset, error) {
	// Resolve the prefix once. It does not depend on the asset name, so
	// deriving it per candidate meant re-parsing the repo URL ~36 times in the
	// probe loop and carrying an error return through three call sites for a
	// failure that can only happen here.
	var assetURL func(asset string) string
	if meta != nil && meta.DownloadURL != "" {
		assetURL = func(asset string) string {
			return expandDownloadTemplate(meta.DownloadURL, name, tag, asset)
		}
	} else {
		base, err := releaseAssetBaseURL(repoURL, tag)
		if err != nil {
			return nil, err
		}
		assetURL = func(asset string) string { return base + asset }
	}

	// A download_url template without {asset} is a single fully-specified
	// URL; there is nothing to select — and no way to locate a checksum
	// manifest, since every candidate name would expand to the same URL.
	if meta != nil && meta.DownloadURL != "" && !strings.Contains(meta.DownloadURL, "{asset}") {
		if !allowUnverified {
			return nil, fmt.Errorf("%w: %s declares a fixed download_url with no {asset} placeholder, so no %s can be located; add {asset} to the template or install with --allow-unverified",
				errUnverifiedAsset, pluginMetadataFileName, checksumsFileName)
		}
		u := expandDownloadTemplate(meta.DownloadURL, name, tag, "")
		return fetchAndVerify(ctx, u, assetNameFromURL(u), "", stagingDir)
	}

	// Preferred path: fetch the checksum manifest and pick from what was
	// actually published.
	for _, cs := range checksumCandidates(name, tag) {
		data, err := httpGetSmall(ctx, assetURL(cs))
		if err != nil {
			continue
		}
		asset, digest, ok := selectAssetFromChecksums(parseChecksums(data), name, tag)
		if !ok {
			// This manifest lists nothing for the platform. Keep going: a
			// stale or hand-written root checksums.txt must not mask a
			// goreleaser manifest under another candidate name, or a
			// published asset still reachable by the probe fallback.
			// Falling through doesn't weaken verification — an attacker
			// who controls the manifest could list a malicious digest
			// directly.
			continue
		}
		return fetchAndVerify(ctx, assetURL(asset), asset, digest, stagingDir)
	}

	// Fallback: probe candidates directly (a release published without a
	// checksum manifest). Nothing authenticates these bytes, so by default an
	// asset found this way is refused rather than installed.
	//
	// The probe still runs when verification is required: it distinguishes
	// "this tag has no release yet" (errAssetNotFound, worth walking down to
	// the next tag) from "the release exists but publishes no checksums"
	// (errUnverifiedAsset, which an older tag wouldn't fix). Getting that
	// wrong would report a missing release for a plugin that simply doesn't
	// ship checksums.
	for _, asset := range assetCandidates(name, tag) {
		fa, err := fetchAndVerify(ctx, assetURL(asset), asset, "", stagingDir)
		switch {
		case errors.Is(err, errAssetNotFound):
			continue
		case err != nil:
			return nil, err
		case allowUnverified:
			return fa, nil
		}
		_ = os.Remove(fa.Path)
		return nil, fmt.Errorf("%w: %s %s publishes %s but no %s to authenticate it; ask the author to publish checksums, or install with --allow-unverified",
			errUnverifiedAsset, name, tag, asset, checksumsFileName)
	}
	return nil, fmt.Errorf("%w for %s/%s at %s %s", errAssetNotFound, runtime.GOOS, runtime.GOARCH, redactURL(repoURL), tag)
}

// assetNameFromURL derives the staging filename for a fully-specified
// download_url. Only the URL path contributes: path.Base on the whole URL
// folds a query string into the name ("entire-run.tar.gz?token=abc"), which
// then misses extractPluginBinary's extension sniff and gets written out as
// a raw binary — a silently broken install (and an invalid filename on
// Windows).
func assetNameFromURL(rawURL string) string {
	if u, err := url.Parse(rawURL); err == nil && u.Path != "" {
		return path.Base(u.Path)
	}
	trimmed := rawURL
	if i := strings.IndexAny(trimmed, "?#"); i >= 0 {
		trimmed = trimmed[:i]
	}
	return path.Base(trimmed)
}

// httpGetSmall fetches a small text resource (checksum manifests).
func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
	if err := requireSecureAssetURL(rawURL); err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
	}
	resp, err := pluginHTTPClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("GET %s: %w", redactURL(rawURL), err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("GET %s: %s", redactURL(rawURL), resp.Status)
	}
	// readWithinLimit, not a bare LimitReader: this fetches checksums.txt, and
	// silently truncating it would drop the line covering our asset — turning a
	// verifiable download into an "unverified" one for a reason nobody could see.
	data, err := readWithinLimit(resp.Body, maxChecksumsSize)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", redactURL(rawURL), err)
	}
	return data, nil
}

// fetchAndVerify downloads rawURL into stagingDir, streaming the SHA-256 as
// it writes. A non-empty wantDigest is enforced; an empty one records the
// computed digest. 404/410 map to errAssetNotFound. Partial files are
// removed on verification failure so a hostile or truncated download never
// lingers in staging.
// Note on credentials: rawURL may carry userinfo, because releaseAssetBaseURL
// derives the asset URL from the repo URL and url.String() re-serializes it.
// The request keeps it — that is how the download authenticates to a private
// forge — but every message below goes through redactURL, since main.go prints
// command errors to stderr and a download failure is an ordinary event
// (network hiccup, 5xx, checksum mismatch), not an exceptional one.
func fetchAndVerify(ctx context.Context, rawURL, asset, wantDigest, stagingDir string) (*fetchedAsset, error) {
	// The asset name is normally one of our own candidates, but the
	// single-URL download_url template path derives it from the URL and a
	// future caller could pass a name straight from a remote manifest.
	// Refuse anything that wouldn't stay inside stagingDir. Backslash is
	// rejected on every platform — it's a separator on Windows, and a
	// literal backslash in an asset name is never legitimate.
	if asset == "" || asset == "." || asset == ".." ||
		strings.ContainsAny(asset, `/\`) || asset != filepath.Base(asset) {
		return nil, fmt.Errorf("unsafe release asset name %q", asset)
	}
	if err := requireSecureAssetURL(rawURL); err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
	}
	resp, err := pluginHTTPClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
	}
	defer resp.Body.Close()
	switch resp.StatusCode {
	case http.StatusOK:
	case http.StatusNotFound, http.StatusGone:
		return nil, fmt.Errorf("%w: GET %s: %s", errAssetNotFound, redactURL(rawURL), resp.Status)
	default:
		return nil, fmt.Errorf("download %s: %s", redactURL(rawURL), resp.Status)
	}

	dest := filepath.Join(stagingDir, asset)
	out, err := os.Create(dest) //nolint:gosec // dest is inside the caller-owned staging dir; asset name came from our candidate list or checksum manifest
	if err != nil {
		return nil, fmt.Errorf("create staging file: %w", err)
	}
	h := sha256.New()
	n, err := io.Copy(io.MultiWriter(out, h), io.LimitReader(resp.Body, maxPluginAssetSize+1))
	closeErr := out.Close()
	if err != nil {
		_ = os.Remove(dest)
		return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
	}
	if closeErr != nil {
		_ = os.Remove(dest)
		return nil, fmt.Errorf("write staging file: %w", closeErr)
	}
	if n > maxPluginAssetSize {
		_ = os.Remove(dest)
		return nil, fmt.Errorf("download %s: exceeds %d byte limit", redactURL(rawURL), int64(maxPluginAssetSize))
	}
	got := hex.EncodeToString(h.Sum(nil))
	if wantDigest != "" && !strings.EqualFold(got, wantDigest) {
		_ = os.Remove(dest)
		return nil, fmt.Errorf("checksum mismatch for %s: got %s, want %s", asset, got, wantDigest)
	}
	return &fetchedAsset{Path: dest, Asset: asset, SHA256: got, Verified: wantDigest != ""}, nil
}

// extractPluginBinary locates the plugin executable inside the downloaded
// asset and writes it to destPath (mode 0755 on Unix). Raw binaries are
// copied; .tar.gz/.tgz and .zip archives are searched for an entry whose
// basename matches entire-<name>[.exe], wherever it sits in the archive.
func extractPluginBinary(assetPath, name, destPath string) error {
	binName := pluginBinaryPrefix + name
	lower := strings.ToLower(assetPath)
	switch {
	case strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz"):
		return extractFromTarGz(assetPath, binName, destPath)
	case strings.HasSuffix(lower, ".zip"):
		return extractFromZip(assetPath, binName, destPath)
	default:
		src, err := os.Open(assetPath) //nolint:gosec // staging-dir file we just wrote
		if err != nil {
			return fmt.Errorf("open asset: %w", err)
		}
		defer src.Close()
		return writeExecutable(src, destPath)
	}
}

// matchesPluginBinary reports whether an archive entry basename is the
// plugin binary, tolerating a Windows extension.
func matchesPluginBinary(entryName, binName string) bool {
	base := path.Base(filepath.ToSlash(entryName))
	if base == binName {
		return true
	}
	return runtime.GOOS == windowsGOOS && strings.EqualFold(base, binName+windowsExeExt)
}

// safeArchiveEntry rejects entry names that could escape an extraction
// root. We only ever extract a single matched file to a fixed dest, so this
// is defense in depth against a hostile archive masking as a plugin.
func safeArchiveEntry(entryName string) bool {
	clean := archiveEntryPath(entryName)
	return !strings.HasPrefix(clean, "../") && !path.IsAbs(clean) && !strings.Contains(entryName, "\x00")
}

// preferredArchiveEntry picks among entries whose basename matches the plugin
// binary. Shallowest path wins, then lexicographic order.
//
// Selection has to be deterministic and independent of archive order. Matching
// is by basename, so an archive can legitimately hold more than one candidate —
// goreleaser writes the binary at the root by default but nests it under a
// versioned directory with wrap_in_directory, and archives also ship things like
// completions/entire-<name>. Taking whichever came first meant the installed
// binary depended on the order the author's tar happened to be built in.
//
// Shallowest-first encodes the convention: the real binary sits at the root, or
// at worst one directory down; a same-named file deeper in the tree is a
// completion script or a doc, not the command.
func preferredArchiveEntry(names []string, binName string) string {
	p := archiveEntryPicker{binName: binName}
	for _, name := range names {
		p.consider(name)
	}
	return p.best
}

// archiveEntryPicker keeps only the best candidate seen so far, so an archive
// can be scanned without materializing every entry name.
//
// That matters because the entry list is remote-controlled and the only prior
// check on it is that the asset's sha256 matched what the release published.
// Entry headers compress extremely well, so the 512 MiB maxPluginAssetSize
// admits tens of millions of them — enough that collecting the names would
// cost gigabytes of heap to end up choosing between the one or two entries a
// real release actually contains. A running minimum costs one string.
type archiveEntryPicker struct {
	binName string
	best    string
	depth   int
}

func (p *archiveEntryPicker) consider(name string) {
	if !safeArchiveEntry(name) || !matchesPluginBinary(name, p.binName) {
		return
	}
	clean := archiveEntryPath(name)
	depth := strings.Count(clean, "/")
	if p.best == "" || depth < p.depth || (depth == p.depth && clean < p.best) {
		p.best, p.depth = clean, depth
	}
}

// archiveEntryPath normalizes an archive entry name to cleaned, slash-separated
// form. Selection and extraction must normalize identically — otherwise the
// entry preferredArchiveEntry picked would not match the one extraction
// compares against, and the install would fail on an archive that contains the
// binary.
func archiveEntryPath(name string) string {
	return path.Clean(filepath.ToSlash(name))
}

// errNoArchiveEntry reports an archive that holds no usable binary, either
// because nothing matched or because the chosen entry vanished between passes.
func errNoArchiveEntry(archivePath, binName string) error {
	return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
}

// walkTarGz calls fn for each regular-file entry in a tar.gz, stopping early
// when fn returns stop. Both the listing pass and the extraction pass go
// through it, so the open/gzip/tar scaffolding exists in one place.
func walkTarGz(archivePath string, fn func(hdr *tar.Header, r io.Reader) (stop bool, err error)) error {
	f, err := os.Open(archivePath) //nolint:gosec // staging-dir file we just wrote
	if err != nil {
		return fmt.Errorf("open archive: %w", err)
	}
	defer f.Close()
	gz, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("open gzip: %w", err)
	}
	defer gz.Close()
	tr := tar.NewReader(gz)
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("read tar: %w", err)
		}
		if hdr.Typeflag != tar.TypeReg {
			continue
		}
		stop, err := fn(hdr, tr)
		if err != nil {
			return err
		}
		if stop {
			return nil
		}
	}
}

// selectTarEntry scans a tar.gz and returns the entry extraction should take,
// holding one candidate name at a time rather than the whole listing.
func selectTarEntry(archivePath, binName string) (string, error) {
	p := archiveEntryPicker{binName: binName}
	if err := walkTarGz(archivePath, func(hdr *tar.Header, _ io.Reader) (bool, error) {
		p.consider(hdr.Name)
		return false, nil
	}); err != nil {
		return "", err
	}
	return p.best, nil
}

func extractFromTarGz(archivePath, binName, destPath string) error {
	// Two passes: a tar stream cannot seek backwards, so choosing among
	// candidates means selecting first and extracting second. The cost is one
	// extra inflation of an archive already capped at maxPluginAssetSize —
	// ~100ms on a 50 MiB archive, against a download measured in seconds —
	// which buys a deterministic choice.
	want, err := selectTarEntry(archivePath, binName)
	if err != nil {
		return err
	}
	if want == "" {
		return errNoArchiveEntry(archivePath, binName)
	}
	found := false
	if err := walkTarGz(archivePath, func(hdr *tar.Header, r io.Reader) (bool, error) {
		if archiveEntryPath(hdr.Name) != want {
			return false, nil
		}
		found = true
		return true, writeExecutable(r, destPath)
	}); err != nil {
		return err
	}
	if !found {
		return errNoArchiveEntry(archivePath, binName)
	}
	return nil
}

func extractFromZip(archivePath, binName, destPath string) error {
	zr, err := zip.OpenReader(archivePath)
	if err != nil {
		return fmt.Errorf("open zip: %w", err)
	}
	defer zr.Close()
	p := archiveEntryPicker{binName: binName}
	for _, f := range zr.File {
		if !f.FileInfo().IsDir() {
			p.consider(f.Name)
		}
	}
	want := p.best
	if want == "" {
		return errNoArchiveEntry(archivePath, binName)
	}
	// zip is random-access, so the chosen entry is reachable directly — no
	// second scan, and no Close deferred inside a loop.
	i := slices.IndexFunc(zr.File, func(f *zip.File) bool {
		return !f.FileInfo().IsDir() && archiveEntryPath(f.Name) == want
	})
	if i < 0 {
		return errNoArchiveEntry(archivePath, binName)
	}
	rc, err := zr.File[i].Open()
	if err != nil {
		return fmt.Errorf("open zip entry: %w", err)
	}
	defer rc.Close()
	return writeExecutable(rc, destPath)
}

// fileSHA256 returns the hex SHA-256 of the file at path. Used to record the
// installed binary's digest and to re-check it in `plugin doctor`.
func fileSHA256(path string) (string, error) {
	f, err := os.Open(path) //nolint:gosec // path is inside the managed plugin tree
	if err != nil {
		return "", fmt.Errorf("open %s: %w", filepath.Base(path), err)
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", fmt.Errorf("read %s: %w", filepath.Base(path), err)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// writeExecutable writes r to destPath with the executable bit set, bounded by
// maxPluginAssetSize. Explicit chmod (not inherited archive mode) because
// zip-built and raw-binary releases routinely lose the bit — the #1
// "downloaded plugin doesn't run" failure.
func writeExecutable(r io.Reader, destPath string) error {
	return writeExecutableLimited(r, destPath, maxPluginAssetSize)
}

// writeExecutableLimited is writeExecutable with an explicit cap, so the
// oversize path is testable without materializing 512 MiB.
//
// The cap lives here rather than in each caller's io.LimitReader because a
// bare LimitReader makes truncation invisible: io.Copy returns a nil error at
// the limit, so an archive entry larger than the cap was silently truncated
// and installed as the plugin binary with the install reporting success. Worse
// since binary_sha256 landed — the digest is computed from the truncated bytes,
// so `plugin doctor` would confirm the corrupt binary as intact. Reading one
// byte past the cap makes the overflow detectable, mirroring fetchAndVerify.
func writeExecutableLimited(r io.Reader, destPath string, limit int64) error {
	// Write to a sibling temp file and rename into place. Two reasons, both
	// load-bearing:
	//
	//  - O_CREATE without O_EXCL follows a symlink at destPath, so a symlink
	//    planted at pkg/<name>/entire-<name> by an earlier malicious plugin
	//    would redirect this write anywhere the user can write (~/.zshrc, a git
	//    hook). Creating a fresh temp name and renaming cannot follow anything.
	//  - Opening destPath with O_TRUNC destroys the working binary before the
	//    new bytes are known-good, so an interrupted or failed copy left the
	//    plugin broken. This path is the *normal* one whenever staging and the
	//    managed dir are on different filesystems (a tmpfs /tmp), not an edge
	//    case.
	tmp, err := os.CreateTemp(filepath.Dir(destPath), ".tmp-"+filepath.Base(destPath)+"-*")
	if err != nil {
		return fmt.Errorf("create staging binary: %w", err)
	}
	tmpName := tmp.Name()
	defer func() { _ = os.Remove(tmpName) }() // no-op once the rename succeeds

	n, err := io.Copy(tmp, io.LimitReader(r, limit+1))
	if err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write binary: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close binary: %w", err)
	}
	if n > limit {
		return fmt.Errorf("plugin binary exceeds the %d byte limit", limit)
	}
	// CreateTemp makes 0600; the dispatcher needs it executable.
	if err := os.Chmod(tmpName, 0o755); err != nil { //nolint:gosec // a plugin binary must be executable
		return fmt.Errorf("set executable bit: %w", err)
	}
	if err := os.Rename(tmpName, destPath); err != nil {
		return fmt.Errorf("place binary: %w", err)
	}
	return nil
}

package cli

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"golang.org/x/mod/semver"
)

// Host-agnostic remote inspection over the git protocol. Version listing
// uses `git ls-remote --tags`, which behaves identically on GitHub, GitLab,
// Gitea/Forgejo, and any self-hosted server, inherits the user's existing
// git auth (SSH agent, credential helpers), and needs no forge REST client.
// The shell-out (vs go-git) is deliberate: this path needs the user's
// credential helpers and proxy config, the same reason hooks.go shells out
// for network-touching operations.

// pluginGitTimeout bounds any single git subprocess this package spawns.
// Without it these calls are unbounded: the root context is WithCancel, not
// WithTimeout, so a black-holed host hangs the command with no output. That
// matters most during dependency planning, which issues one ls-remote plus up
// to two shallow clones per dependency against author-controlled URLs, before
// the user has confirmed anything. The asset download already caps at 5
// minutes; this is the git half of the same bound.
const pluginGitTimeout = 2 * time.Minute

// Output caps for git subprocesses. cmd.Output() buffers the whole of stdout in
// memory, and both stdout-producing calls read remote-controlled data: ls-remote
// returns whatever refs a repository advertises, and `show <tag>:file` returns
// whatever an author committed. A hostile repository could otherwise hand us an
// arbitrarily large response and take the process down.
const (
	// maxGitRefsOutput bounds `ls-remote`. Each ref line is ~60 bytes, so this
	// still admits a repository with hundreds of thousands of tags.
	maxGitRefsOutput = 16 << 20
	// maxPluginMetadataSize bounds entire-plugin.yml. It holds a name, a
	// description, a URL template and a short requires list; 64 KiB is orders
	// of magnitude more than any real one needs.
	maxPluginMetadataSize = 64 << 10
	// maxGitNoOutput is for commands run with --quiet that should print
	// nothing. A non-empty stdout there means something unexpected happened.
	maxGitNoOutput = 4 << 10
	// maxGitStderr bounds captured stderr. Capping stdout alone left the same
	// hole open on the other channel: the remote controls what git echoes, and
	// a bytes.Buffer grows without limit. git's own diagnostics are short, so
	// this only ever truncates a hostile one.
	maxGitStderr = 64 << 10
)

// errOutputTooLarge fails a write once a subprocess exceeds its cap.
var errOutputTooLarge = errors.New("output exceeds the limit")

// limitedWriter buffers at most limit bytes of a subprocess stream.
//
// Used as cmd.Stdout/cmd.Stderr rather than reading a pipe ourselves: os/exec
// closes the pipe as soon as a write fails, so an oversize response kills the
// child immediately, where reading a pipe and returning early left Wait
// blocked on a full pipe until pluginGitTimeout — a two-minute hang in exactly
// the case the cap exists to handle.
//
// Overflow policy differs per stream. stdout fails, because a truncated
// payload is not the payload. stderr absorbs and drops the excess: diagnostics
// are best-effort and must never fail a command git itself completed. Either
// way the buffered prefix is kept, so fetchPluginMetadataAtTag can still match
// git's message — git emits that before any remote-supplied bulk.
type limitedWriter struct {
	buf            bytes.Buffer
	limit          int64
	exceeded       bool
	failOnOverflow bool
}

func (w *limitedWriter) Write(p []byte) (int, error) {
	room := w.limit - int64(w.buf.Len())
	if int64(len(p)) <= room {
		n, err := w.buf.Write(p)
		return n, err //nolint:wrapcheck // bytes.Buffer.Write never errors
	}
	if room > 0 {
		_, _ = w.buf.Write(p[:room])
	}
	w.exceeded = true
	if w.failOnOverflow {
		return 0, errOutputTooLarge
	}
	return len(p), nil
}

// runGitDiscard runs a git command that is expected to print nothing, and
// reports only whether it succeeded. Every --quiet call site wants this shape.
func runGitDiscard(ctx context.Context, args ...string) error {
	_, err := runGitQuiet(ctx, maxGitNoOutput, args...)
	return err
}

// runGitQuiet runs git and returns stdout, with a bounded deadline and an
// environment that cannot block on a prompt.
//
// LC_ALL=C/LANG=C keep git's messages in English: fetchPluginMetadataAtTag decides
// the benign "no metadata file" case by substring-matching git's stderr, and
// git builds with NLS translate those strings — on a localized host every
// plugin repo without an entire-plugin.yml (the documented default) would
// otherwise fail to install. BatchMode stops ssh prompting for a key
// passphrase on /dev/tty, which GIT_TERMINAL_PROMPT does not cover — but only
// when the user has not set GIT_SSH_COMMAND themselves.
func runGitQuiet(ctx context.Context, maxOutput int64, args ...string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(ctx, pluginGitTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", args...)
	env := append(os.Environ(), "GIT_TERMINAL_PROMPT=0", "LC_ALL=C", "LANG=C")
	// Only supply a batch-mode ssh when the user has not configured one. A
	// blanket GIT_SSH_COMMAND would override both the env var and
	// core.sshCommand, discarding a custom ssh invocation (jump hosts, an
	// explicit identity) and breaking clones that only work through it.
	// Respecting an existing setting costs the passphrase-prompt guard in that
	// one case, which is the right trade — the user chose that command.
	if _, set := os.LookupEnv("GIT_SSH_COMMAND"); !set {
		env = append(env, "GIT_SSH_COMMAND=ssh -oBatchMode=yes")
	}
	cmd.Env = env

	// Not cmd.Output(): that buffers stdout to EOF with no bound, and leaves
	// stderr unbounded too. Both streams get a cap instead.
	stdout := &limitedWriter{limit: maxOutput, failOnOverflow: true}
	stderr := &limitedWriter{limit: maxGitStderr}
	cmd.Stdout, cmd.Stderr = stdout, stderr
	runErr := cmd.Run()
	switch {
	case stdout.exceeded:
		// Checked before runErr: killing the child is how the cap is enforced,
		// so the exit status here is a symptom, not the diagnosis.
		return nil, fmt.Errorf("git %s: stdout exceeds the %d-byte limit", args[0], maxOutput)
	case runErr != nil:
		// stderr is folded in here rather than left for callers to dig out of
		// ExitError: cmd.Stderr is set, so ExitError.Stderr is empty now.
		return stdout.buf.Bytes(), fmt.Errorf("git %s: %w%s", args[0], runErr, stderrDetail(stderr.buf.Bytes()))
	}
	return stdout.buf.Bytes(), nil
}

// stderrDetail formats captured git stderr for an error message. git's stderr
// is where the actionable detail lives, and it can echo a remote URL, so it is
// scrubbed for credentials on the way out.
func stderrDetail(raw []byte) string {
	text := strings.TrimSpace(string(raw))
	if text == "" {
		return ""
	}
	return ": " + redactCredentials(text)
}

// redactURL strips credentials from a URL so they never reach stderr,
// .entire/logs/ — which lives in the user's working tree and is collected
// wholesale by `entire doctor bundle` — or a persisted manifest.yml.
//
// Delegates to the repo-wide helper rather than reimplementing it: that one also
// drops the query string, which matters here because release hosts redirect to
// signed CDN URLs carrying ?token=/X-Amz-Signature=. A local implementation that
// only stripped userinfo would have leaked those.
func redactURL(raw string) string {
	return gitremote.RedactURL(raw)
}

// redactCredentials removes userinfo from any URL appearing in free text, for
// git's stderr where we do not know which URL was echoed.
var credentialInURL = regexp.MustCompile(`([a-zA-Z][a-zA-Z0-9+.-]*://)[^/@\s]*@`)

func redactCredentials(text string) string {
	return credentialInURL.ReplaceAllString(text, "${1}")
}

// gitURLSchemes are the transports a plugin or index repository URL may use in
// production.
//
// http:// and git:// are deliberately absent. Both are unauthenticated and
// unencrypted, and the catalog fetched over them decides which repositories
// install without a confirmation prompt — so an attacker who can rewrite the
// transport chooses the binary. That is strictly worse than the plaintext-asset
// case the download path already refuses.
//
// file:// is absent too, and only accepted under test (see allowLocalGitURL).
// Nothing in production needs it: a file:// plugin repository cannot even
// complete an install, because releaseAssetBaseURL requires an http(s) repo URL
// to derive the asset location. Its only real consumer was the test suite, and
// a security allowlist should not be widened to pay for test convenience —
// especially when the alternative transports a test could use are worse
// (git daemon serves git://, which is exactly what was removed above).
var gitURLSchemes = []string{"https://", "ssh://"}

// envAllowFileRemotes lets a spawned test binary accept file:// remotes.
// testing.Testing() is false in a subprocess, so the integration harness — which
// runs the real `entire` against file:// fixture repos — has to say so through
// the environment, the same way it passes the rest of its isolation down.
const envAllowFileRemotes = "ENTIRE_TEST_ALLOW_FILE_REMOTES"

// fileRemotesAllowed is the policy itself, taking its two inputs as arguments
// so it can be tested directly. In-process, testing.Testing() is always true
// where a test runs, so a test that reads the ambient value can only ever
// observe "allowed" — the spawned-binary case, which is the one the env var
// exists for, is unreachable without parameterizing it.
func fileRemotesAllowed(underTest bool, envValue string) bool {
	return underTest || envValue != ""
}

// allowLocalGitURL reports whether file:// remotes are acceptable. True only
// under `go test`, or in a binary a test harness spawned.
//
// Setting the env var is not a meaningful weakening: anyone able to set it on
// the victim's machine already has code execution. What it buys is that the
// shipped allowlist has no local-filesystem transport, so a hostile catalog
// entry cannot use one to probe the filesystem.
//
// A var, not a func, so a test can flip it and exercise the shipped rejection.
// Same seam pattern as postPluginVersionCheck in this package.
//
//nolint:gochecknoglobals // test seam; see above
var allowLocalGitURL = func() bool {
	return fileRemotesAllowed(testing.Testing(), os.Getenv(envAllowFileRemotes))
}

// scpLikeGitURL matches git's scp-like syntax (user@host:path) — the form
// `git@github.com:owner/repo.git` uses. Requires a user@, a host without a
// slash, and a colon before the path, so it cannot match a bare option or a
// local path.
var scpLikeGitURL = regexp.MustCompile(`^[A-Za-z0-9._~-]+@[A-Za-z0-9._-]+:[^\s]`)

// validatePluginRepoURL rejects anything that is not recognizably a git
// repository URL before it reaches the git CLI as a positional argument.
//
// This is a security boundary, not a nicety. These URLs arrive from
// attacker-influenced places — index.json entries, another plugin's
// entire-plugin.yml requires[], a stored manifest, --index — and git parses an
// option-shaped positional as an option. `--upload-pack=<cmd>` is
// shell-interpreted and runs against the *ambient* repo when no positional
// remains, so an entry like "--upload-pack=curl … | sh; git-upload-pack" would
// execute arbitrary commands during an index-resolved install, which never
// prompts. validatePluginName already refuses a leading '-' on names for the
// same reason.
//
// Local remotes — both bare absolute paths and file:// URLs — are rejected
// outside tests. A local plugin repository could not complete an install anyway
// (releaseAssetBaseURL needs an http(s) repo URL to locate the asset), and
// `install ./path` is the supported way to use a local build. Callers
// additionally pass "--" before positionals, so an option-shaped value would be
// refused by git even if it got this far.
func validatePluginRepoURL(rawURL string) error {
	u := strings.TrimSpace(rawURL)
	if u == "" {
		return errors.New("repository URL is empty")
	}
	if strings.HasPrefix(u, "-") {
		return fmt.Errorf("repository URL %q must not start with '-'", redactURL(rawURL))
	}
	for _, scheme := range gitURLSchemes {
		if strings.HasPrefix(u, scheme) && len(u) > len(scheme) {
			return nil
		}
	}
	if strings.HasPrefix(u, "file://") && len(u) > len("file://") && allowLocalGitURL() {
		return nil
	}
	if scpLikeGitURL.MatchString(u) {
		return nil
	}
	return fmt.Errorf("repository URL %q must use one of %s or git's user@host:path form",
		redactURL(rawURL), strings.Join(gitURLSchemes, ", "))
}

// listRemoteSemverTags returns the repo's semver tags ("v"-prefixed or
// bare), sorted descending by semantic version. Non-semver tags are
// ignored.
func listRemoteSemverTags(ctx context.Context, repoURL string) ([]string, error) {
	if err := validatePluginRepoURL(repoURL); err != nil {
		return nil, err
	}
	// --refs suppresses peeled ^{} entries for annotated tags. "--" keeps an
	// option-shaped URL from being parsed as a git option.
	out, err := runGitQuiet(ctx, maxGitRefsOutput, "ls-remote", "--tags", "--refs", "--", repoURL)
	if err != nil {
		return nil, fmt.Errorf("list tags of %s: %w", redactURL(repoURL), err)
	}
	var tags []string
	for _, line := range strings.Split(string(out), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 2 {
			continue
		}
		tag := strings.TrimPrefix(fields[1], "refs/tags/")
		canon := canonicalSemver(tag)
		if !semver.IsValid(canon) {
			continue
		}
		// Prereleases are excluded: semver ranks v2.0.0-rc1 above stable
		// v1.9.0, so an author pushing a release candidate would migrate every
		// user onto it on the next `plugin upgrade --all`. --pin installs an
		// exact tag and bypasses this listing, which is the opt-in.
		if semver.Prerelease(canon) != "" {
			continue
		}
		tags = append(tags, tag)
	}
	// Stable, so tags that compare equal (v1.0.0 vs 1.0.0, or +build metadata,
	// which semver ignores) resolve in a deterministic order.
	sort.SliceStable(tags, func(i, j int) bool {
		return semver.Compare(canonicalSemver(tags[i]), canonicalSemver(tags[j])) > 0
	})
	return tags, nil
}

// canonicalSemver maps a tag to the "v"-prefixed form x/mod/semver expects.
func canonicalSemver(tag string) string {
	if strings.HasPrefix(tag, "v") {
		return tag
	}
	return "v" + tag
}

// fetchPluginMetadataAtTag reads entire-plugin.yml at the given tag without
// a user-visible clone: a blobless shallow clone into a discarded temp dir,
// falling back to a plain shallow clone for servers that don't allow
// partial-clone filters (uploadpack.allowFilter defaults to off outside the
// big forges). Returns (nil, nil) when the repo has no metadata file —
// metadata is optional by design.
func fetchPluginMetadataAtTag(ctx context.Context, repoURL, tag string) (*PluginMetadata, error) {
	if err := validatePluginRepoURL(repoURL); err != nil {
		return nil, err
	}
	tmp, err := os.MkdirTemp("", "entire-plugin-meta-")
	if err != nil {
		return nil, fmt.Errorf("create temp dir: %w", err)
	}
	defer os.RemoveAll(tmp)

	cloneArgs := func(filter bool) []string {
		args := []string{"clone", "--depth", "1", "--no-checkout", "--branch", tag, "--quiet"}
		if filter {
			args = append(args, "--filter=blob:none")
		}
		// "--" so an option-shaped URL can't be parsed as a git option.
		return append(args, "--", repoURL, tmp)
	}
	if err := runGitDiscard(ctx, cloneArgs(true)...); err != nil {
		// Retry without the filter; the clone dir may be half-created.
		if rmErr := os.RemoveAll(tmp); rmErr != nil {
			return nil, fmt.Errorf("clean temp clone dir: %w", rmErr)
		}
		if err := runGitDiscard(ctx, cloneArgs(false)...); err != nil {
			return nil, fmt.Errorf("clone %s at %s: %w", redactURL(repoURL), tag, err)
		}
	}
	// `git show <rev>:<path>` peels annotated tags and, in a blobless
	// clone, lazily fetches just this one blob from the promisor remote.
	out, err := runGitQuiet(ctx, maxPluginMetadataSize, "-C", tmp, "show", tag+":"+pluginMetadataFileName)
	if err != nil {
		// Missing file and missing tag both surface as exit 128; only the
		// missing-file case is benign. Disambiguate via stderr.
		if strings.Contains(err.Error(), "does not exist") ||
			strings.Contains(err.Error(), "exists on disk, but not in") {
			return nil, nil //nolint:nilnil // metadata is optional
		}
		return nil, fmt.Errorf("read %s at %s: %w", pluginMetadataFileName, tag, err)
	}
	return ParsePluginMetadata(out)
}

// pluginNameFromRepoURL derives the bare plugin name from a repository URL
// basename: .../entire-run(.git) → "run". Used when entire-plugin.yml is
// absent or doesn't declare a name.
func pluginNameFromRepoURL(repoURL string) (string, error) {
	trimmed := strings.TrimSuffix(strings.TrimSuffix(repoURL, "/"), ".git")
	base := trimmed
	if i := strings.LastIndexAny(trimmed, "/:"); i >= 0 {
		base = trimmed[i+1:]
	}
	if !strings.HasPrefix(base, pluginBinaryPrefix) {
		return "", fmt.Errorf("repository basename %q does not start with %q; declare a name in %s", base, pluginBinaryPrefix, pluginMetadataFileName)
	}
	name := strings.TrimPrefix(base, pluginBinaryPrefix)
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	return name, nil
}

package cli

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// Plugin discovery rides on a git-synced index, krew-style: the index is
// itself a git repository containing index.json, shallow-cloned into the
// user cache and re-pulled on a TTL. No hosted service, no forge REST API —
// any git server can host an index. An organization points the CLI at an
// internal catalog with ENTIRE_PLUGIN_INDEX_URL or --index; see
// resolvePluginIndexURL for why a committed settings file cannot.
const (
	// defaultPluginIndexURL is the built-in curated index.
	defaultPluginIndexURL = "https://github.com/entireio/plugin-index"
	// pluginIndexEnvVar overrides the index URL (forwarded to plugin
	// children automatically via the ENTIRE_ allowlist prefix).
	pluginIndexEnvVar = "ENTIRE_PLUGIN_INDEX_URL"
	// pluginIndexFileName is the catalog file at the index repo root.
	pluginIndexFileName = "index.json"
	// pluginIndexSchemaVersion is the index schema this CLI reads. Advisory:
	// a higher declared version logs a warning and is still read (see
	// loadPluginIndexFromDir).
	pluginIndexSchemaVersion = 1
	// pluginIndexSyncMarker records the last successful sync time as the
	// marker file's mtime. Untracked, so fetch/reset never touches it.
	pluginIndexSyncMarker = ".entire-last-sync"
	// maxPluginIndexSize bounds index.json. krew's catalog carries a few
	// hundred entries; 8 MiB leaves room for far more without letting a hostile
	// index exhaust memory.
	maxPluginIndexSize = 8 << 20
	// pluginIndexTTL is how long a synced copy is considered fresh. Fixed
	// rather than configurable: `plugin index update` already forces a refresh
	// and stale-on-offline already covers a failed one, so a knob here tuned a
	// problem solved twice over while costing a settings load per sync.
	pluginIndexTTL = 24 * time.Hour
)

// PluginIndex is the parsed catalog. Decoding is deliberately lenient
// (unknown fields ignored) so an index that grows new fields doesn't break
// older CLI versions fleet-wide.
type PluginIndex struct {
	// Version is the declared schema version. Advisory only — see
	// loadPluginIndexFromDir for why it isn't enforced.
	Version int                `json:"version"`
	Plugins []PluginIndexEntry `json:"plugins"`
}

// PluginIndexEntry describes one plugin in the catalog.
type PluginIndexEntry struct {
	Name        string `json:"name"`
	RepoURL     string `json:"repo_url"`
	Description string `json:"description,omitempty"`
	Official    bool   `json:"official,omitempty"`
	// Platforms lists supported GOOS values when the plugin doesn't ship
	// the full matrix; empty means all.
	Platforms []string `json:"platforms,omitempty"`
}

// Find returns the entry with the given bare name, or nil.
func (idx *PluginIndex) Find(name string) *PluginIndexEntry {
	if idx == nil {
		return nil
	}
	for i := range idx.Plugins {
		if idx.Plugins[i].Name == name {
			return &idx.Plugins[i]
		}
	}
	return nil
}

// Search returns entries whose name or description contains term
// (case-insensitive). An empty term returns everything.
func (idx *PluginIndex) Search(term string) []PluginIndexEntry {
	if idx == nil {
		return nil
	}
	if term == "" {
		return idx.Plugins
	}
	t := strings.ToLower(term)
	var out []PluginIndexEntry
	for _, e := range idx.Plugins {
		if strings.Contains(strings.ToLower(e.Name), t) || strings.Contains(strings.ToLower(e.Description), t) {
			out = append(out, e)
		}
	}
	return out
}

// FindByRepoURL returns the entry published at repoURL, or nil. Comparison
// normalizes the .git suffix and trailing slashes.
//
// The name matters as much as the presence: a URL install of a listed repo is
// trusted and never prompts, so the catalog entry is the only thing that says
// what the plugin should be called. Without it the remote picks the name
// unchallenged, and --force would replace whichever plugin it named.
func (idx *PluginIndex) FindByRepoURL(repoURL string) *PluginIndexEntry {
	if idx == nil {
		return nil
	}
	want := normalizeRepoURL(repoURL)
	for i := range idx.Plugins {
		if normalizeRepoURL(idx.Plugins[i].RepoURL) == want {
			return &idx.Plugins[i]
		}
	}
	return nil
}

func normalizeRepoURL(u string) string {
	return strings.TrimSuffix(strings.TrimRight(strings.TrimSpace(u), "/"), ".git")
}

// resolvePluginIndexURL applies the documented precedence: --index flag >
// ENTIRE_PLUGIN_INDEX_URL > built-in default.
//
// Repo-level settings are deliberately NOT a source. .entire/settings.json is a
// committed file resolved from the working directory, and an index-listed repo
// installs with no confirmation prompt — so honoring it there meant a cloned
// repository could redirect the catalog and get an attacker-chosen binary
// downloaded, chmod 0755, and linked onto the user's PATH without a prompt.
// The value of that setting was precisely that contributors got a different
// catalog *without knowing*, which is the vulnerability stated as a feature; it
// cannot be kept and made safe, only removed or made visible.
//
// Organizations wanting an internal catalog set ENTIRE_PLUGIN_INDEX_URL, which
// applies across repos rather than per-repo, and cannot be chosen by content
// the user merely checked out. This matches Go, where no repo-committed file
// can redirect GOPROXY; npm's per-project registry override is the
// cautionary counter-example.
func resolvePluginIndexURL(flagValue string) string {
	if flagValue != "" {
		return flagValue
	}
	if v := os.Getenv(pluginIndexEnvVar); v != "" {
		return v
	}
	return defaultPluginIndexURL
}

// pluginIndexCacheDir is the per-URL local copy. Keyed by a hash of the
// URL so switching indexes (or per-repo overrides) never serves one
// catalog's cache for another.
func pluginIndexCacheDir(indexURL string) (string, error) {
	cache := userdirs.Cache()
	if cache == "" {
		return "", errors.New("cannot resolve user cache directory")
	}
	sum := sha256.Sum256([]byte(normalizeRepoURL(indexURL)))
	return filepath.Join(cache, "plugin-index", hex.EncodeToString(sum[:6])), nil
}

// SyncPluginIndex returns the catalog for indexURL, cloning or refreshing
// the local copy as needed. force bypasses the TTL. When a refresh fails
// but a previous copy exists, the stale copy is used with a warning logged
// — discovery shouldn't hard-fail because a laptop is offline.
func SyncPluginIndex(ctx context.Context, indexURL string, force bool) (*PluginIndex, error) {
	// The index URL reaches `git clone` as a positional; it can come from
	// --index or ENTIRE_PLUGIN_INDEX_URL, neither of which the settings
	// validator sees. Reject non-URLs before git can read one as an option.
	if err := validatePluginRepoURL(indexURL); err != nil {
		return nil, fmt.Errorf("plugin index URL: %w", err)
	}
	dir, err := pluginIndexCacheDir(indexURL)
	if err != nil {
		return nil, err
	}

	// The cache dir is shared by every concurrent `entire plugin` invocation
	// and syncing it is destructive: RemoveAll + clone on the cold path,
	// fetch + `reset --hard FETCH_HEAD` on the warm one. Serialize the whole
	// sync-and-read under an advisory lock, the same way discovery/cache.go
	// guards its shared cache files. Without it, one process cloning while
	// another reads index.json surfaces a spurious "no readable index.json",
	// and two cold syncs racing can leave exactly the half-created directory
	// the sweep below exists to recover from.
	//
	// The lock file is a *sibling* of the cache dir, not inside it: RemoveAll
	// on the dir would otherwise delete the lock file while we hold it.
	if err := os.MkdirAll(filepath.Dir(dir), 0o750); err != nil {
		return nil, fmt.Errorf("create index cache dir: %w", err)
	}
	release, err := flock.AcquireContext(ctx, dir+".lock")
	if err != nil {
		return nil, fmt.Errorf("lock plugin index cache: %w", err)
	}
	defer release()

	marker := filepath.Join(dir, pluginIndexSyncMarker)
	// Lstat, not Stat: this asks whether *our* cache dir contains a clone.
	// Following a symlink would let a link pointing elsewhere answer yes.
	_, statErr := os.Lstat(filepath.Join(dir, ".git"))
	cloned := statErr == nil

	fresh := false
	if cloned && !force {
		if info, err := os.Lstat(marker); err == nil {
			// A negative age means the marker is dated in the future (clock
			// rollback, restored backup, bad container clock). Treating that as
			// fresh would freeze the catalog until someone ran `index update`
			// by hand, so only a non-negative age inside the window counts.
			if age := time.Since(info.ModTime()); age >= 0 && age < pluginIndexTTL {
				fresh = true
			}
		}
	}

	switch {
	case !cloned:
		// A previously interrupted clone can leave a partial directory
		// without .git. git refuses to clone into a non-empty target, so
		// without this sweep, discovery would stay wedged until the user
		// cleared the cache by hand.
		if err := os.RemoveAll(dir); err != nil {
			return nil, fmt.Errorf("clear stale index cache: %w", err)
		}
		if err := runGitDiscard(ctx, "clone", "--depth", "1", "--quiet", "--", indexURL, dir); err != nil {
			return nil, fmt.Errorf("clone plugin index %s: %w", redactURL(indexURL), err)
		}
		touchFile(marker)
	case !fresh:
		if err := refreshPluginIndexClone(ctx, dir); err != nil {
			logging.Warn(ctx, "plugin index refresh failed; using cached copy",
				slog.String("index", redactURL(indexURL)), slog.String("error", err.Error()))
		} else {
			touchFile(marker)
		}
	}

	return loadPluginIndexFromDir(ctx, dir, indexURL)
}

// refreshPluginIndexClone updates an existing shallow clone to the remote
// tip regardless of the remote's default branch name.
func refreshPluginIndexClone(ctx context.Context, dir string) error {
	if err := runGitDiscard(ctx, "-C", dir, "fetch", "--depth", "1", "--quiet", "origin", "HEAD"); err != nil {
		return fmt.Errorf("fetch: %w", err)
	}
	if err := runGitDiscard(ctx, "-C", dir, "reset", "--hard", "--quiet", "FETCH_HEAD"); err != nil {
		return fmt.Errorf("reset: %w", err)
	}
	return nil
}

func touchFile(path string) {
	now := time.Now()
	if err := os.Chtimes(path, now, now); err == nil {
		return
	}
	if f, err := os.Create(path); err == nil { //nolint:gosec // marker file inside our cache dir
		_ = f.Close()
	}
}

func loadPluginIndexFromDir(ctx context.Context, dir, indexURL string) (*PluginIndex, error) {
	// Bounded: the catalog is cloned from a remote repository, so its size is
	// not ours to trust. A few hundred entries with descriptions is well under
	// a megabyte.
	data, err := readFileLimited(filepath.Join(dir, pluginIndexFileName), maxPluginIndexSize)
	if err != nil {
		return nil, fmt.Errorf("plugin index %s has no readable %s: %w", redactURL(indexURL), pluginIndexFileName, err)
	}
	var idx PluginIndex
	if err := json.Unmarshal(data, &idx); err != nil {
		return nil, fmt.Errorf("parse %s from %s: %w", pluginIndexFileName, redactURL(indexURL), err)
	}
	// version is recorded, not enforced. Refusing an unrecognized value would
	// protect against a migration that can never happen: the index is one
	// shared resource read by every CLI version ever shipped, so bumping it
	// would break discovery fleet-wide with no gradual rollout and no undo for
	// installed binaries. An incompatible schema therefore ships at a new path
	// (index-v2.json, another branch, another repo), which needs no gate here.
	// Enforcing it only ever fired by accident — most painfully on an index
	// that simply omits the field (version 0), which told the author to
	// upgrade the CLI when the fix was in their own file. Hand-written
	// internal catalogs are a first-class case (ENTIRE_PLUGIN_INDEX_URL).
	//
	// Additive changes, the ones that actually happen, are already absorbed:
	// decoding ignores unknown fields and unreadable entries are dropped
	// below. Degrading per entry beats refusing the catalog.
	if idx.Version > pluginIndexSchemaVersion {
		logging.Warn(ctx, "plugin index declares a newer schema version; reading what this CLI understands",
			slog.String("index", redactURL(indexURL)),
			slog.Int("declared_version", idx.Version),
			slog.Int("understood_version", pluginIndexSchemaVersion))
	}
	var valid []PluginIndexEntry
	for _, e := range idx.Plugins {
		// repo_url is validated here, not just at the git boundary: an
		// index-resolved install is treated as trusted and never prompts, so
		// a hostile catalog entry must not reach the git CLI at all.
		if validatePluginName(e.Name) != nil || validatePluginRepoURL(e.RepoURL) != nil {
			continue // tolerate bad entries rather than failing the catalog
		}
		valid = append(valid, e)
	}
	idx.Plugins = valid
	return &idx, nil
}

