13	)
14	
15	// Dependency handling is install-time only. Dispatch stays zero-cost: a
16	// plugin invokes its deps as entire-<dep> via PATH at runtime (the managed
17	// bin dir is prepended for plugin children), and `entire plugin doctor`
18	// reports drift after the fact. There is deliberately no version-range
19	// solver — requirements carry at most a minimum version.
20	
21	// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
22	// practice; the bound turns a metadata cycle that slips past the visited
23	// set (e.g. two names aliasing one repo) into an error instead of a hang.
24	const maxDepDepth = 10
25	
26	// DepAction is one planned dependency install or upgrade.
27	type DepAction struct {
28		Name       string
29		RepoURL    string
30		MinVersion string
31		// Upgrade is true when the dependency is installed but below
32		// MinVersion; the action reinstalls at the latest tag.
33		Upgrade bool
34		// CurrentTag is the installed tag for upgrades.
35		CurrentTag string
36	}
37	
38	// DepPlan is the result of resolving a plugin's transitive requirements.
39	type DepPlan struct {
40		Actions []DepAction
41		// Warnings are non-blocking observations, e.g. a dependency satisfied
42		// from raw $PATH whose version cannot be verified.
43		Warnings []string
44	}
45	
46	// PlanDependencyInstalls resolves the transitive requirements of rootReqs
47	// into ordered install/upgrade actions. Missing dependencies must be
48	// resolvable to a repo URL via the requirement itself or the index. The
49	// visited set plus a depth bound make cycles an error path, not a hang.
50	func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
51		plan := &DepPlan{}
52		// name -> strictest min_version considered so far, not a plain seen-set:
53		// see planDeps.
54		considered := map[string]string{}
55		if err := planDeps(ctx, rootReqs, idx, plan, considered, 0); err != nil {
56			return nil, err
57		}
58		return plan, nil
59	}
60	
61	// stricterMinVersion reports whether a demands a higher minimum than b.
62	// An empty string means "no minimum": nothing is stricter than it, and any
63	// concrete minimum is stricter than it.
64	func stricterMinVersion(a, b string) bool {
65		switch {
66		case a == "":
67			return false
68		case b == "":
69			return true
70		default:
71			return semver.Compare(canonicalSemver(a), canonicalSemver(b)) > 0
72		}
73	}
74	
75	// upsertDepAction keeps one action per plugin name, replacing an earlier
76	// entry when a stricter requirement supersedes it.
77	func upsertDepAction(plan *DepPlan, action DepAction) {
78		for i := range plan.Actions {
79			if plan.Actions[i].Name == action.Name {
80				plan.Actions[i] = action
81				return
82			}
83		}
84		plan.Actions = append(plan.Actions, action)
85	}
86	
87	// addDepWarning appends a warning unless it is already present. Re-visiting a
88	// name under a stricter constraint can re-derive the same observation, and
89	// printing it twice would just look like a bug.
90	func addDepWarning(plan *DepPlan, warning string) {
91		if warning == "" || slices.Contains(plan.Warnings, warning) {
92			return
93		}
94		plan.Warnings = append(plan.Warnings, warning)
95	}
96	
97	func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, considered map[string]string, depth int) error {
98		if depth > maxDepDepth {
99			return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
100		}
101		for _, req := range reqs {
102			// Keyed by name *and* gated on the strictest min_version seen so far,
103			// not a plain seen-set. In a diamond where two requirers demand
104			// different minimums of the same plugin (A needs C >= v1, B needs
105			// C >= v2), a name-only set skipped B's stricter constraint entirely:
106			// an installed C satisfying v1 produced no action and no warning, so
107			// the install completed leaving B running against a too-old C. Doctor
108			// caught it afterwards — it walks each manifest's requirements
109			// independently — but the install should plan the upgrade, not defer
110			// the discovery.
111			if prev, seen := considered[req.Name]; seen && !stricterMinVersion(req.MinVersion, prev) {
112				continue
113			}
114			// Past the guard this name is either new or strictly stricter than
115			// what was recorded, so this requirement's minimum is the one to keep.
116			considered[req.Name] = req.MinVersion
117	
118			status, err := dependencySatisfied(req)
119			if err != nil {
120				return err
121			}
122			addDepWarning(plan, status.Warning)
123			if status.Satisfied {
124				// An already-satisfied managed dependency can itself have
125				// gaps (e.g. its own dep was removed with --force since
126				// install). Walk its recorded requirements — offline, from
127				// the manifest — so installing a parent repairs the whole
128				// chain instead of stopping at the first satisfied node.
129				// PATH/local-dev installs have no manifest; doctor covers
130				// those.
131				if status.Manifest != nil {
132					if err := planDeps(ctx, status.Manifest.Requires, idx, plan, considered, depth+1); err != nil {
133						return err
134					}
135				}
136				continue
137			}
138	
139			action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
140			if m := status.Manifest; m != nil {
141				// Installed but below min_version: upgrade in place from its
142				// recorded repo.
143				action.Upgrade = true
144				action.CurrentTag = m.Tag
145				action.RepoURL = m.RepoURL
146			} else {
147				// Missing: resolve by name through the index, which is the only
148				// source. See PluginRequirement for why an author-supplied URL is
149				// not accepted here.
150				e := idx.Find(req.Name)
151				if e == nil {
152					return fmt.Errorf("dependency %q is not installed and is not in the plugin index; ask the plugin author to get it listed (try 'entire plugin search %s'), or install it yourself from its repository URL first", req.Name, req.Name)
153				}
154				action.RepoURL = e.RepoURL
155			}
156			upsertDepAction(plan, action)
157	
158			// Recurse into what the dependency itself requires, using metadata
159			// only — nothing is downloaded during planning. Inspection
160			// failures don't fail the plan (the install will surface hard
161			// errors itself), but they must not be silent either: a confirmed
162			// plan that quietly omitted nested dependencies would look
163			// complete while leaving gaps for doctor to find.
164			tag := ""
165			if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
166				tag = tags[0]
167			}
168			if tag == "" {
169				addDepWarning(plan, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, redactURL(action.RepoURL)))
170				continue
171			}
172			meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
173			if err != nil {
174				addDepWarning(plan, fmt.Sprintf("could not read %s for %q at %s; its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", pluginMetadataFileName, req.Name, tag))
175				continue
176			}
177			if meta == nil {
178				continue // no metadata file: no declared dependencies
179			}
180			if err := planDeps(ctx, meta.Requires, idx, plan, considered, depth+1); err != nil {
181				return err
182			}
183		}
184		return nil
185	}
186	
187	// dependencySatisfied checks whether a requirement is already met, in
188	// order: managed install with manifest (version-checkable) → managed entry
189	// without manifest (local-dev, version unknown) → raw $PATH (version
190	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
191	// (main.go restores it for built-ins), so LookPath here sees only
192	// raw-PATH plugins — managed entries are checked explicitly first.
193	// depStatus is what dependencySatisfied concluded about one requirement.
194	type depStatus struct {
195		// Satisfied is true when nothing needs installing.
196		Satisfied bool
197		// Manifest is the dependency's install manifest, or nil for a local-dev
198		// install or a raw-$PATH binary. Returned rather than re-loaded by callers:
199		// every one of them needed it, so the file was being read three times per
200		// requirement.
201		Manifest *PluginManifest
202		// Warning is a non-blocking observation, e.g. a min_version that cannot be
203		// verified because the dependency came from $PATH.
204		Warning string
205	}
206	
207	func dependencySatisfied(req PluginRequirement) (depStatus, error) {
208		m, err := LoadPluginManifest(req.Name)
209		if err != nil {
210			return depStatus{}, err
211		}
212		if m != nil {
213			satisfied := req.MinVersion == "" ||
214				semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0
215			// Not satisfied here means installed-but-too-old, which is the upgrade
216			// path in planDeps.
217			return depStatus{Satisfied: satisfied, Manifest: m}, nil
218		}
219		installed, err := FindInstalledPlugin(req.Name)
220		if err != nil {
221			return depStatus{}, err
222		}
223		if installed != nil {
224			return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "a local-dev install")}, nil
225		}
226		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
227			return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "$PATH")}, nil
228		}
229		return depStatus{}, nil
230	}
231	
232	func unverifiableVersionWarning(req PluginRequirement, source string) string {
233		if req.MinVersion == "" {
234			return ""
235		}
236		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
237	}
238	
239	// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
240	// allowUnverified is inherited from the root install so a single
241	// --allow-unverified covers the whole transitive set the user confirmed,
242	// rather than failing partway through on the first dependency without
243	// published checksums.
244	func ExecuteDepPlan(ctx context.Context, plan *DepPlan, allowUnverified bool) ([]*RemoteInstallResult, error) {
245		results := make([]*RemoteInstallResult, 0, len(plan.Actions))
246		for _, a := range plan.Actions {
247			// The plan named this dependency and the user confirmed that name; an
248			// install landing under a different one would never satisfy the
249			// requirement, leaving doctor to report it missing forever.
250			res, err := InstallPluginFromRepo(ctx, a.RepoURL, a.Name, RemoteInstallOptions{
251				Force: a.Upgrade, AllowUnverified: allowUnverified,
252			})
253			if err != nil {
254				return results, fmt.Errorf("install dependency %q: %w", a.Name, err)
255			}
256			results = append(results, res)
257			// Verify the outcome, not just that an install happened. The install
258			// takes the newest published tag, which may still be below the minimum
259			// the plan computed — in which case reporting success would silently
260			// defeat the guarantee the plan was built on, and leave doctor
261			// complaining forever about a dependency we just "installed".
262			if a.MinVersion != "" &&
263				semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(a.MinVersion)) < 0 {
264				return results, fmt.Errorf("dependency %q: newest release is %s but %s or later is required; ask the plugin author to publish a release that meets it",
265					a.Name, res.Manifest.Tag, a.MinVersion)
266			}
267		}
268		return results, nil
269	}
270	
271	// DependentsOf returns the names of managed plugins whose manifests list
272	// name as a requirement — the remove guard. Computed by scanning
273	// pkg/*/manifest.yml; no extra state to maintain.
274	func DependentsOf(name string) ([]string, error) {
275		manifests, err := ListPluginManifests()
276		if err != nil {
277			return nil, err
278		}
279		var out []string
280		for _, m := range manifests {
281			for _, req := range m.Requires {
282				if req.Name == name {
283					out = append(out, m.Name)
284					break
285				}
286			}
287		}
288		return out, nil
289	}
290	
291	// PluginDoctorIssue is one problem found by RunPluginDoctor.
292	type PluginDoctorIssue struct {
293		Plugin  string
294		Problem string
295		Fix     string
296	}
297	
298	// RunPluginDoctor checks every managed plugin: bin entry present, dangling
299	// local-dev symlinks, dependency presence and min_versions, and (macOS) a
300	// quarantine attribute that would block execution.
301	func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
302		var issues []PluginDoctorIssue
303	
304		installed, err := ListInstalledPlugins()
305		if err != nil {
306			return nil, err
307		}
308		installedByName := map[string]*InstalledPlugin{}
309		for _, p := range installed {
310			installedByName[p.Name] = p
311			if p.Symlink {
312				if _, err := exec.LookPath(p.Path); err != nil {
313					issues = append(issues, PluginDoctorIssue{
314						Plugin:  p.Name,
315						Problem: "managed entry is a dangling or non-executable link to " + p.LinkTarget,
316						Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
317					})
318				}
319			}
320			if q := quarantinedPath(ctx, p.Path); q != "" {
321				issues = append(issues, PluginDoctorIssue{
322					Plugin:  p.Name,
323					Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
324					Fix:     "run: xattr -d com.apple.quarantine " + q,
325				})
326			}
327		}
328	
329		manifests, err := ListPluginManifests()
330		if err != nil {
331			return nil, err
332		}
333		for _, m := range manifests {
334			if installedByName[m.Name] == nil {
335				issues = append(issues, PluginDoctorIssue{
336					Plugin:  m.Name,
337					Problem: "has an install manifest but no entry in the managed bin dir",
338					Fix:     "reinstall: " + reinstallCommand(m),
339				})
340			}
341			issues = append(issues, checkManagedBinaryIntegrity(m)...)
342			for _, req := range m.Requires {
343				status, err := dependencySatisfied(req)
344				if err != nil {
345					return nil, err
346				}
347				switch {
348				case status.Satisfied && status.Warning != "":
349					issues = append(issues, PluginDoctorIssue{Plugin: m.Name, Problem: status.Warning, Fix: ""})
350				case !status.Satisfied:
351					if dep := status.Manifest; dep != nil {
352						issues = append(issues, PluginDoctorIssue{
353							Plugin:  m.Name,
354							Problem: fmt.Sprintf("requires %s >= %s but %s is installed", req.Name, req.MinVersion, dep.Tag),
355							Fix:     "run: entire plugin upgrade " + req.Name,
356						})
357					} else {
358						issues = append(issues, PluginDoctorIssue{
359							Plugin:  m.Name,
360							Problem: fmt.Sprintf("requires %q, which is not installed", req.Name),
361							Fix:     "run: entire plugin install " + req.Name,
362						})
363					}
364				}
365			}
366		}
367		return issues, nil
368	}
369	
370	// reinstallCommand is the suggested repair for a broken managed install. It
371	// carries --allow-unverified for a plugin installed that way, because the
372	// reinstall re-runs the checksum requirement and would otherwise fail with
373	// errUnverifiedAsset — handing the user a command that cannot succeed on
374	// exactly the plugins doctor flags.
375	func reinstallCommand(m *PluginManifest) string {
376		cmd := fmt.Sprintf("entire plugin install %s --force", redactURL(m.RepoURL))
377		if m.Unverified {
378			cmd += " --allow-unverified"
379		}
380		if m.Pinned {
381			// Without this the repair silently unpins: the reinstall would take the
382			// newest tag and write a manifest with Pinned cleared, so a plugin the
383			// user deliberately held at a version would start tracking latest as a
384			// side effect of fixing something unrelated.
385			cmd += " --pin " + m.Tag
386		}
387		return cmd
388	}
389	
390	// checkManagedBinaryIntegrity re-hashes a managed plugin's binary and
391	// compares it to the digest recorded at install time, catching a binary
392	// swapped out under the managed directory after install.
393	//
394	// This checks the pkg/ binary, which is the copy the manifest describes and
395	// the target bin/ links to. Where the bin/ entry is a copy rather than a link
396	// (Windows without Developer Mode), a tampered copy is not covered — the
397	// dangling/non-executable link check above is what guards that surface.
398	//
399	// A manifest without BinarySHA256 predates integrity recording, so there is
400	// nothing to compare and silence is correct; nagging about it would only tell
401	// the user to reinstall a plugin that is probably fine.
402	func checkManagedBinaryIntegrity(m *PluginManifest) []PluginDoctorIssue {
403		var issues []PluginDoctorIssue
404		if m.Unverified {
405			issues = append(issues, PluginDoctorIssue{
406				Plugin:  m.Name,
407				Problem: fmt.Sprintf("installed from %s without checksum verification (the release published no %s)", m.Tag, checksumsFileName),
408				Fix:     "if the author has since published checksums, re-run: entire plugin upgrade " + m.Name,
409			})
410		}
411		if m.BinarySHA256 == "" {
412			return issues
413		}
414		dir, err := PluginPkgDir(m.Name)
415		if err != nil {
416			return issues
417		}
418		binPath := filepath.Join(dir, pluginBinaryName(m.Name))
419		got, err := fileSHA256(binPath)
420		if err != nil {
421			issues = append(issues, PluginDoctorIssue{
422				Plugin:  m.Name,
423				Problem: "managed binary is missing or unreadable: " + err.Error(),
424				Fix:     "reinstall: " + reinstallCommand(m),
425			})
426			return issues
427		}
428		if !strings.EqualFold(got, m.BinarySHA256) {
429			issues = append(issues, PluginDoctorIssue{
430				Plugin:  m.Name,
431				Problem: "managed binary no longer matches the digest recorded at install; it was modified or replaced outside entire",
432				Fix:     "reinstall from the recorded source: " + reinstallCommand(m),
433			})
434		}
435		return issues
436	}
437	
438	// quarantinedPath returns the path to flag when the file (or its symlink
439	// target) carries com.apple.quarantine. Best-effort, macOS only; any error
440	// means "not quarantined". The attribute appears when a user manually
441	// drops a browser-downloaded binary into the managed dir — CLI downloads
442	// don't set it.
443	//
444	// Checking the bin entry is sufficient even though remote installs link
445	// bin/entire-<name> to the real binary under pkg/: macOS xattr follows
446	// symlinks by default (-s is the flag to act on the link itself), so both
447	// the probe here and the suggested `xattr -d` fix operate on the target.
448	func quarantinedPath(ctx context.Context, path string) string {
449		if runtime.GOOS != darwinGOOS {
450			return ""
451		}
452		out, err := exec.CommandContext(ctx, "xattr", "-p", "com.apple.quarantine", path).Output()
453		if err != nil || strings.TrimSpace(string(out)) == "" {
454			return ""
455		}
456		return path
457	}
