54		// when it differs from the one just installed. --force is *for* replacing,
55		// so this is not an error — but the confirmation for a URL install names a
56		// URL, never the plugin it is about to overwrite, and the remote picks that
57		// name. Surfacing it is what turns an uninformed replacement into an
58		// informed one, and gives the user the URL to put things back.
59		ReplacedFrom string
60	}
61	
62	// InstallPluginFromRepo installs a plugin from a git repository URL.
63	// Dependency resolution deliberately does not happen here — callers
64	// (the install command) plan and confirm dependency installs first.
65	// expectedName is the plugin name the caller has already committed to — the
66	// index entry the user asked for, the requirement being satisfied, or the
67	// plugin being upgraded. Pass "" only for a bare `install <url>`, where the
68	// repository legitimately names itself; installRepoAtTag explains why a
69	// mismatch is otherwise fatal.
70	//
71	// It is a required argument rather than an options field on purpose. As a
72	// field it could be silently omitted, and omitting it reopens a no-prompt
73	// name-substitution hole; as an argument, passing "" is a visible choice at
74	// the call site.
75	func InstallPluginFromRepo(ctx context.Context, repoURL, expectedName string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
76		repoURL = strings.TrimRight(repoURL, "/")
77	
78		var tags []string
79		if opts.Pin != "" {
80			tags = []string{opts.Pin}
81		} else {
82			var err error
83			tags, err = listRemoteSemverTags(ctx, repoURL)
84			if err != nil {
