88				return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
89			}
90			if len(tags) > maxTagFallbacks {
91				tags = tags[:maxTagFallbacks]
92			}
93		}
