134		//    requirement, so dependencySatisfied/doctor reported it missing forever
135		//    and every future parent install re-attempted it.
136		//
137		// Fatal rather than a warning: every caller that sets ExpectedName has
138		// already made a trust decision about *that* name, and silently honoring a
139		// different one voids it. A legitimate rename is a catalog or requirement
140		// to fix, and the message says so.
141		if expectedName != "" && name != expectedName {
142			return nil, fmt.Errorf(
143				"%s declares plugin name %q but %q was requested; refusing to install under a name that was not asked for (update the plugin index entry or the requirement if the plugin was renamed)",
144				redactURL(repoURL), name, expectedName)
