233		if err != nil {
234			return nil, err
235		}
236		return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta, ReplacedFrom: replacedFrom}, nil
237	}
238	
239	// UpgradeOutcome describes what UpgradeInstalledPlugin did.
240	type UpgradeOutcome struct {
241		Name string
242		// Pinned: skipped because the manifest is pinned.
243		Pinned bool
244		// UpToDate: already at the newest tag.
245		UpToDate bool
