250	// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
251	// plugin and reinstalls when it differs from the manifest's tag. Plugins
252	// without a manifest (local-dev symlinks) are not upgradable.
253	func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
