278		// installed unverified shouldn't start failing on upgrade, and one
279		// installed verified must not silently downgrade to unverified.
280		res, err := InstallPluginFromRepo(ctx, m.RepoURL, name, RemoteInstallOptions{
281			Force: true, AllowUnverified: m.Unverified,
